import { Group, Mesh, PlaneGeometry, CylinderGeometry, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Color } = ctx.THREE;

  // Helper to create gradient material
  const createGradientMaterial = () => {
    const top = new Color('#191921');
    const bottom = new Color('#121218');
    const mat = new MeshStandardNodeMaterial({
      roughness: 0.6,
      metalness: 0.25,
      clearcoat: 0.15,
      transparent: true,
      opacity: 0,
    });
    mat.colorNode = mix(
      new vec3(top.r, top.g, top.b),
      new vec3(bottom.r, bottom.g, bottom.b),
      uv().y
    );
    return mat;
  };

  const root = new Group();
  root.name = 'FeatureTriptych';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const cardCount = 3;
  const cardW = 1.5;
  const cardH = 1.9;
  const gap = 0.25;
  const totalW = cardCount * cardW + (cardCount - 1) * gap;
  const startX = -totalW / 2 + cardW / 2;

  const cards = [];
  const masterTL = gsap.timeline({ paused: true });

  for (let i = 0; i < cardCount; i++) {
    const card = new Group();
    card.position.set(startX + i * (cardW + gap), 0, 0);
    card.position.y = 0.2; // start offset for entrance

    // Border plane
    const borderGeom = new PlaneGeometry(cardW, cardH);
    const borderMat = new MeshStandardNodeMaterial({
      color: new Color('#26262f'),
      roughness: 0.6,
      metalness: 0.25,
      clearcoat: 0.15,
      transparent: true,
      opacity: 0,
    });
    const borderMesh = new Mesh(borderGeom, borderMat);
    card.add(borderMesh);

    // Inner gradient plane
    const innerW = cardW - 0.012;
    const innerH = cardH - 0.012;
    const innerGeom = new PlaneGeometry(innerW, innerH);
    const innerMat = createGradientMaterial();
    const innerMesh = new Mesh(innerGeom, innerMat);
    innerMesh.position.set(0, 0, 0.001);
    card.add(innerMesh);

    // Icon seat disc
    const discGeom = new CylinderGeometry(0.2, 0.2, 0.05, 32);
    const discMat = new MeshStandardNodeMaterial({
      color: new Color('#16161d'),
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2,
    });
    const discMesh = new Mesh(discGeom, discMat);
    const discY = cardH / 2 - 0.2;
    discMesh.position.set(0, discY, 0.01);
    card.add(discMesh);

    // Glyph (icon)
    const glyphItem = items[i * 3];
    const glyph = ctx.fontAtlas.createText(glyphItem.text, {
      fontSize: glyphItem.typography?.fontSize ?? 20,
      color: '#ff2a38',
      align: 'center',
    });
    glyph.position.set(0, discY, 0.02);
    card.add(glyph);

    // Title
    const titleItem = items[i * 3 + 1];
    const title = ctx.fontAtlas.createText(titleItem.text, {
      fontSize: titleItem.typography?.fontSize ?? 20,
      color: '#e8ecf2',
      align: 'left',
    });
    const titleY = discY - 0.25 - 0.1;
    title.position.set(-innerW / 2 + 0.05, titleY, 0.02);
    card.add(title);

    // Body
    const bodyItem = items[i * 3 + 2];
    const body = ctx.fontAtlas.createText(bodyItem.text, {
      fontSize: bodyItem.typography?.fontSize ?? 13,
      color: '#e8ecf2',
      align: 'left',
      maxWidthPx: 200,
    });
    const bodyY = titleY - 0.2;
    body.position.set(-innerW / 2 + 0.05, bodyY, 0.02);
    card.add(body);

    // Hover animation
    const hoverTL = gsap.timeline({ paused: true });
    hoverTL.to(card.position, {
      y: 0.06,
      z: 0.12,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    });
    // Emissive intensity on glyph material (if available)
    const glyphMat = (glyph as any).children?.[0]?.material ?? null;
    if (glyphMat) {
      hoverTL.to(glyphMat, {
        emissiveIntensity: 2.2,
        duration: 0.18,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      }, 0);
    }

    // Entrance animation (staggered)
    masterTL.fromTo(
      card.position,
      { y: 0.2 },
      { y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      i * 0.08
    );
    masterTL.fromTo(
      [borderMat, innerMat],
      { opacity: 0 },
      { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      i * 0.08
    );

    cards.push({ group: card, borderMat, innerMat, hoverTL, glyphMat });
    root.add(card);
  }

  masterTL.play();

  // Event handlers attached to userData
  root.userData.handlers = {
    hover: () => {
      cards.forEach(c => c.hoverTL.play());
    },
    unhover: () => {
      cards.forEach(c => c.hoverTL.reverse());
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    masterTL.kill();
    cards.forEach(c => {
      c.hoverTL.kill();
      c.borderMat.dispose();
      c.innerMat.dispose();
      c.group.traverse(obj => {
        if (obj.isMesh) {
          obj.geometry.dispose();
        }
      });
    });
  };

  // Load optional background texture if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then(tex => {
      // Apply to each inner plane as overlay (optional)
      cards.forEach(c => {
        c.innerMat.map = tex;
        c.innerMat.needsUpdate = true;
      });
    });
  }

  return root;
}
